package com.akitaattribute.mobfarmblock.data;
import com.akitaattribute.mobfarmblock.MobFarmBlockMod; import com.akitaattribute.mobfarmblock.mob.*; import com.google.gson.*; import net.fabricmc.fabric.api.resource.IdentifiableResourceReloadListener; import net.minecraft.resource.ResourceManager; import net.minecraft.util.Identifier; import net.minecraft.util.profiler.Profiler;
import java.io.InputStreamReader; import java.nio.charset.StandardCharsets; import java.util.*; import java.util.concurrent.*;
/** Loads explicit JSON profiles for custom, Cobblemon, or Pixelmon-style mobs without capturing entities. */
public class MobProfileReloadListener implements IdentifiableResourceReloadListener { public Identifier getFabricId(){return MobFarmBlockMod.id("mob_profiles");} public CompletableFuture<Void> reload(Synchronizer s, ResourceManager m, Profiler p1, Profiler p2, Executor bg, Executor game){return CompletableFuture.supplyAsync(()->load(m),bg).thenCompose(s::whenPrepared).thenAcceptAsync(map->map.forEach(DropProfileRegistry::put),game);} private Map<Identifier,DropProfile> load(ResourceManager m){Map<Identifier,DropProfile> out=new HashMap<>(); Gson g=new Gson(); m.findResources("mob_profiles",id->id.getPath().endsWith(".json")).forEach((id,res)->{try(var r=new InputStreamReader(res.getInputStream(), StandardCharsets.UTF_8)){JsonObject o=g.fromJson(r,JsonObject.class); Identifier mob=Identifier.of(o.get("mob").getAsString()); List<DropRule> rules=new ArrayList<>(); for(JsonElement e:o.getAsJsonArray("drops")){JsonObject d=e.getAsJsonObject(); rules.add(new DropRule(Identifier.of(d.get("item").getAsString()),d.has("chance")?d.get("chance").getAsDouble():1,d.has("min")?d.get("min").getAsInt():1,d.has("max")?d.get("max").getAsInt():1,d.has("affectedByLooting")&&d.get("affectedByLooting").getAsBoolean(),d.has("lootingChanceBonus")?d.get("lootingChanceBonus").getAsDouble():0,d.has("lootingMaxBonus")?d.get("lootingMaxBonus").getAsInt():0));} JsonObject x=o.has("xp")?o.getAsJsonObject("xp"):new JsonObject(); out.put(mob,new DropProfile(rules,new XpProfile(x.has("min")?x.get("min").getAsInt():0,x.has("max")?x.get("max").getAsInt():0)));}catch(Exception ex){MobFarmBlockMod.LOGGER.warn("Bad mob profile {}",id,ex);} }); return out;} }
